import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        edges = []
        adj = [[] for _ in range(n + 1)]

        for i in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            edges.append((u, v))
            adj[u].append(v)
            adj[v].append(u)

        parent = [0] * (n + 1)
        order = []
        stack = [1]
        visited = [False] * (n + 1)
        visited[1] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        order.reverse()

        edge_company = {}
        company_counter = 1
        max_company_roads = 0
        company_roads_count = {}

        def get_company():
            nonlocal company_counter
            company_counter += 1
            return company_counter

        for u in order:
            if u == 1:
                continue

            p = parent[u]
            edge_key = (min(u, p), max(u, p))

            companies_at_u = set()
            companies_at_p = set()

            for v in adj[u]:
                if v == p:
                    continue
                if not visited[v]:
                    continue
                e_key = (min(u, v), max(u, v))
                if e_key in edge_company:
                    companies_at_u.add(edge_company[e_key])

            for v in adj[p]:
                if v == u:
                    continue
                e_key = (min(p, v), max(p, v))
                if e_key in edge_company:
                    companies_to_check = set()
                    if v != parent[p]:
                        companies_to_check.add(edge_company[e_key])
                    else:
                        pass
                if e_key in edge_company:
                    companies_at_p.add(edge_company[e_key])

            if len(companies_at_u) < 2 and len(companies_at_p) < 2:
                if companies_at_u and companies_at_p:
                    common = companies_at_u & companies_at_p
                    if common:
                        chosen = list(common)[0]
                    else:
                        chosen = list(companies_at_u)[0]
                elif companies_at_u:
                    chosen = list(companies_at_u)[0]
                elif companies_at_p:
                    chosen = list(companies_at_p)[0]
                else:
                    chosen = get_company()
            else:
                chosen = get_company()

            edge_company[edge_key] = chosen
            if chosen not in company_roads_count:
                company_roads_count[chosen] = 0
            company_roads_count[chosen] += 1
            max_company_roads = max(max_company_roads, company_roads_count[chosen])

        assignment = []
        for u, v in edges:
            key = (min(u, v), max(u, v))
            assignment.append(str(edge_company[key]))

        results.append(str(max_company_roads))
        results.append(" ".join(assignment))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
